import random

def play_game():
    """Plays a single game of Rock, Paper, Scissors with the user."""

    # Define the possible choices
    choices = ["rock", "paper", "scissors"]

    # Get the user's choice
    user_choice = input("Enter your choice (rock, paper, scissors): ").lower()

    # Ensure the user's choice is valid
    while user_choice not in choices:
        print("Invalid choice. Please enter 'rock', 'paper', or 'scissors'.")
        user_choice = input("Enter your choice: ").lower()

    # Generate a random choice for the computer
    computer_choice = random.choice(choices)

    # Determine the winner and print the result
    if user_choice == "rock":
        if computer_choice == "scissors":
            print(f"You win! The computer chose {computer_choice}.")
        else:
            print(f"The computer wins! The computer chose {computer_choice}.")
    elif user_choice == "paper":
        if computer_choice == "rock":
            print(f"You win! The computer chose {computer_choice}.")
        else:
            print(f"You lose! The computer chose {computer_choice}.")
    elif user_choice == "scissors":
        if computer_choice == "paper":
            print(f"You win! The computer chose {computer_choice}.")
        else:
            print(f"The computer wins! The computer chose {computer_choice}.")

# Play multiple games (or just one)
num_games = int(input("How many games would you like to play? (1 or more): "))
for _ in range(num_games):
    play_game()
    print("\n")  # Add a newline for better readability
```

This program defines a function `play_game()` that takes care of generating a random choice for the computer, prompting the user for their choice, and determining the winner. The function can be called multiple times to play multiple games.
